import { Link, useNavigate } from 'react-router-dom';
import API from '../api/axios';
import toast from 'react-hot-toast';

export default function Navbar() {
  const navigate = useNavigate();
  const userInfo = JSON.parse(localStorage.getItem('userInfo'));
  const adminInfo = JSON.parse(localStorage.getItem('adminInfo'));

  const handleLogout = async () => {
    try {
      if (userInfo) await API.post('/users/logout');
      if (adminInfo) await API.post('/companies/logout');
      
      localStorage.removeItem('userInfo');
      localStorage.removeItem('adminInfo');
      toast.success('Logged out securely');
      navigate('/');
    } catch (error) {
      toast.error('Logout failed');
    }
  };

  return (
    <nav className="bg-white border-b border-gray-200 shadow-sm sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 items-center">
          
          <div className="flex-shrink-0 flex items-center">
            <Link to="/" className="text-xl font-extrabold text-indigo-600 tracking-tight">
              Pay<span className="text-gray-900">Tap</span>
            </Link>
          </div>

          <div className="hidden md:flex space-x-8 items-center">
            {!userInfo && !adminInfo && (
              <>
                <Link to="/user/login" className="text-sm font-medium text-gray-500 hover:text-indigo-600 transition">Student Login</Link>
                <Link to="/admin/login" className="text-sm font-medium text-gray-500 hover:text-indigo-600 transition">Admin Portal</Link>
              </>
            )}

            {userInfo && (
              <Link to="/user/dashboard" className="text-sm font-medium text-gray-700 hover:text-indigo-600 transition">My Dashboard</Link>
            )}

            {adminInfo && (
              <>
                <Link to="/admin/checkout" className="text-sm font-medium text-gray-700 hover:text-indigo-600 transition">Terminal</Link>
                <Link to="/admin/register" className="text-sm font-medium text-gray-700 hover:text-indigo-600 transition">Link Cards</Link>
              </>
            )}

            {(userInfo || adminInfo) && (
              <button 
                onClick={handleLogout}
                className="bg-gray-100 hover:bg-gray-200 text-gray-800 px-4 py-2 rounded-lg text-sm font-semibold transition"
              >
                Logout
              </button>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
}
